 <?php if($generatedCode):?><section class="access-code-reveal"><div><span>Code temporaire</span><strong data-sync-code><?= $e($generatedCode)?></strong><small>Valable 30 minutes · usage unique</small></div><button class="button secondary" type="button" data-copy-code>Copier le code</button></section><?php endif?>
