  <div class="access-relation-list"><?php foreach($grants as$g):$currentIsClient=(int)$organization['id']===(int)$g['client_organization_id'];$mustDecide=$g['status']==='Pending'&&(($g['request_origin']==='AgencyCode'&&$currentIsClient)||($g['request_origin']==='ClientInvitation'&&!$currentIsClient));?>
   <article class="access-relation"><div class="access-relation-main"><div class="access-avatar"><?= $e(mb_substr($currentIsClient?$g['agency_name']:$g['client_name'],0,1))?></div><div><span class="access-kicker"><?= $currentIsClient?'Agence autorisee':'Entreprise cliente'?></span><h3><?= $e($currentIsClient?$g['agency_name']:$g['client_name'])?></h3><div class="access-meta"><span class="access-status status-<?= strtolower($e($g['status']))?>"><?= $e($g['status'])?></span><span><?= $g['request_origin']==='AgencyCode'?'Demande par code':($g['request_origin']==='ClientInvitation'?'Invitation client':'Creation administrative')?></span><span><?= $e(date('d/m/Y H:i',strtotime($g['updated_at'])))?></span></div></div></div>
