<script>document.querySelector('[data-copy-code]')?.addEventListener('click',async e=>{const code=document.querySelector('[data-sync-code]')?.textContent.trim();if(!code)return;await navigator.clipboard.writeText(code);e.currentTarget.textContent='Code copie'});</script>